let overrideDate = null;
try {
  const q = $('On Demand Trigger').first().json.query || {};
  overrideDate = q.date || null;
} catch (e) { /* triggered by the schedule, not on-demand -- no override */ }

const pad = n => String(n).padStart(2, '0');
let yearNum, monthNum, dayNum;

if (overrideDate && /^\d{4}-\d{2}-\d{2}$/.test(overrideDate)) {
  // A specific date passed via ?date=YYYY-MM-DD on the on-demand webhook --
  // lets the correction notification email's 'Send Report Now' button always
  // resend the report for the date that email was actually about, even if
  // clicked days later (otherwise it would always mean 'yesterday from now').
  [yearNum, monthNum, dayNum] = overrideDate.split('-').map(Number);
} else {
  const now = new Date();
  const istOffset = 5.5 * 3600000;
  const nowIst = new Date(now.getTime() + istOffset);
  const todayIst = new Date(Date.UTC(nowIst.getUTCFullYear(), nowIst.getUTCMonth(), nowIst.getUTCDate()));
  const yesterdayIst = new Date(todayIst.getTime() - 86400000);
  yearNum = yesterdayIst.getUTCFullYear(); monthNum = yesterdayIst.getUTCMonth() + 1; dayNum = yesterdayIst.getUTCDate();
}

const day = yearNum + '-' + pad(monthNum) + '-' + pad(dayNum);
const dayFormatted = pad(dayNum) + '/' + pad(monthNum) + '/' + yearNum;
const monthStart = yearNum + '-' + pad(monthNum) + '-01';
const MONTH_NAMES = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const monthLabel = MONTH_NAMES[monthNum - 1] + "'" + String(yearNum).slice(2);
return [{ json: { day, dayFormatted, monthStart, monthLabel } }];

const d = $('Compute Dates').first().json.day;
// Team attribution:
//  - Answer/Outbound: by resolved_sip (agent_alt_numbers-resolved agent_number)
//    matched against our 4 known ResMed agents (Gulshan Khan, Avijit Dey,
//    Mohit Kumar, Admin/Sagarika Bose) -- whoever actually picked up.
//  - Agent Missed / Queue Missed: by skill, since there's no real
//    answering agent to resolve -- 'Renting CPAP and BiPAP' is ResMed's
//    own in-house team's queue, everything else is ours.
// Validated against 2026-10-19 data -- every cell matched the client report exactly.
const OUR_SIPS = "'10170226','10170201','10170203','10170200'";
const query = `SELECT
  SUM(CASE WHEN r.call_type='INBOUND' AND r.disposition='Answer' THEN 1 ELSE 0 END) AS ib_answer_total,
  SUM(CASE WHEN r.call_type='INBOUND' AND r.disposition='Answer' AND r.resolved_sip IN (${OUR_SIPS}) THEN 1 ELSE 0 END) AS ib_answer_om,
  SUM(CASE WHEN r.call_type='INBOUND' AND r.disposition='Answer' AND r.resolved_sip IS NOT NULL AND r.resolved_sip NOT IN (${OUR_SIPS}) THEN 1 ELSE 0 END) AS ib_answer_resmed,
  SUM(CASE WHEN r.disposition='Agent Missed' THEN 1 ELSE 0 END) AS agent_missed_total,
  SUM(CASE WHEN r.disposition='Agent Missed' AND (r.skill IS NULL OR r.skill <> 'Renting CPAP and BiPAP') THEN 1 ELSE 0 END) AS agent_missed_om,
  SUM(CASE WHEN r.disposition='Agent Missed' AND r.skill = 'Renting CPAP and BiPAP' THEN 1 ELSE 0 END) AS agent_missed_resmed,
  SUM(CASE WHEN r.disposition='Queue Missed' THEN 1 ELSE 0 END) AS queue_missed_total,
  SUM(CASE WHEN r.disposition='Queue Missed' AND (r.skill IS NULL OR r.skill <> 'Renting CPAP and BiPAP') THEN 1 ELSE 0 END) AS queue_missed_om,
  SUM(CASE WHEN r.disposition='Queue Missed' AND r.skill = 'Renting CPAP and BiPAP' THEN 1 ELSE 0 END) AS queue_missed_resmed,
  SUM(CASE WHEN r.disposition='IVR Missed' AND TIME(r.start_time) BETWEEN ps.login_time AND ps.logout_time AND (ps.days_pattern='All days' OR DAYOFWEEK(r.start_time)<>1) THEN 1 ELSE 0 END) AS ivr_missed_wh,
  SUM(CASE WHEN r.disposition='IVR Missed' AND NOT (TIME(r.start_time) BETWEEN ps.login_time AND ps.logout_time AND (ps.days_pattern='All days' OR DAYOFWEEK(r.start_time)<>1)) THEN 1 ELSE 0 END) AS ivr_missed_nwh,
  SUM(CASE WHEN r.call_type='OUTBOUND' THEN 1 ELSE 0 END) AS ob_total,
  SUM(CASE WHEN r.call_type='OUTBOUND' AND r.resolved_sip IN (${OUR_SIPS}) THEN 1 ELSE 0 END) AS ob_om,
  SUM(CASE WHEN r.call_type='OUTBOUND' AND r.resolved_sip IS NOT NULL AND r.resolved_sip NOT IN (${OUR_SIPS}) THEN 1 ELSE 0 END) AS ob_resmed,
  SUM(CASE WHEN r.call_type='OUTBOUND' AND r.disposition='Answer' THEN 1 ELSE 0 END) AS ob_answer,
  SUM(CASE WHEN r.call_type='OUTBOUND' AND r.disposition='Answer' AND r.resolved_sip IN (${OUR_SIPS}) THEN 1 ELSE 0 END) AS ob_answer_om,
  SUM(CASE WHEN r.call_type='OUTBOUND' AND r.disposition='Answer' AND r.resolved_sip IS NOT NULL AND r.resolved_sip NOT IN (${OUR_SIPS}) THEN 1 ELSE 0 END) AS ob_answer_resmed,
  SUM(CASE WHEN r.call_type='OUTBOUND' AND r.disposition='No Answer' THEN 1 ELSE 0 END) AS ob_noanswer,
  SUM(CASE WHEN r.call_type='OUTBOUND' AND r.disposition='No Answer' AND r.resolved_sip IN (${OUR_SIPS}) THEN 1 ELSE 0 END) AS ob_noanswer_om,
  SUM(CASE WHEN r.call_type='OUTBOUND' AND r.disposition='No Answer' AND r.resolved_sip IS NOT NULL AND r.resolved_sip NOT IN (${OUR_SIPS}) THEN 1 ELSE 0 END) AS ob_noanswer_resmed
FROM (
  SELECT cd.*, COALESCE(aan.sip, cd.agent_number) AS resolved_sip
  FROM calls.call_disposition cd
  LEFT JOIN calls.agent_alt_numbers aan ON aan.service_id = cd.service_id AND aan.alt_number = cd.agent_number
  WHERE cd.service_id = 1702 AND cd.call_date = '${d}'
) r
JOIN calls.process_shift_schedule ps ON ps.service_id = 1702;`;
return [{ json: { query } }];

const d = $('Compute Dates').first().json.day;
// corrected_category overrides the note-derived category whenever a TL has
// submitted a fix via the Tracker form's 'Call Tag Correction' type (e.g. an
// agent mistagged an Inbound call with an Outbound 'OB - ...' category) --
// so once corrected, every future report run picks it up automatically.
const query = `SELECT cd.received_by, cd.note, cd.ivr, ctc.corrected_category
FROM calls.call_disposition cd
LEFT JOIN calls.call_tag_corrections ctc ON ctc.txn_id = cd.txn_id
WHERE cd.service_id = 1702 AND cd.call_date = '${d}' AND cd.call_type='INBOUND' AND cd.disposition='Answer';`;
return [{ json: { query } }];

const dates = $('Compute Dates').first().json;
const r = $('Exec Query Table1').first().json;
function n(v) { return Number(v) || 0; }

const ibAnswer = { total: n(r.ib_answer_total), om: n(r.ib_answer_om), resmed: n(r.ib_answer_resmed) };
const agentMissed = { total: n(r.agent_missed_total), om: n(r.agent_missed_om), resmed: n(r.agent_missed_resmed) };
const queueMissed = { total: n(r.queue_missed_total), om: n(r.queue_missed_om), resmed: n(r.queue_missed_resmed) };
const ivrMissedWh = n(r.ivr_missed_wh);
const ivrMissedNwh = n(r.ivr_missed_nwh);

// "Inbound" header total deliberately excludes IVR-level drop-offs (they
// never reached a real queue/agent) -- matches the client report exactly.
const ibTotal = { total: ibAnswer.total + agentMissed.total + queueMissed.total,
  om: ibAnswer.om + agentMissed.om + queueMissed.om,
  resmed: ibAnswer.resmed + agentMissed.resmed + queueMissed.resmed };

const obTotal = n(r.ob_total), obOm = n(r.ob_om), obResmed = n(r.ob_resmed);
const obAnswer = { total: n(r.ob_answer), om: n(r.ob_answer_om), resmed: n(r.ob_answer_resmed) };
const obNoAnswer = { total: n(r.ob_noanswer), om: n(r.ob_noanswer_om), resmed: n(r.ob_noanswer_resmed) };

const grandTotal = { total: ibTotal.total + obTotal, om: ibTotal.om + obOm, resmed: ibTotal.resmed + obResmed };
// "Total Handled" = Inbound Answered (only actually-connected inbound counts
// as handled) + all Outbound dialed (effort counts even if unanswered).
const totalHandled = { total: ibAnswer.total + obTotal, om: ibAnswer.om + obOm, resmed: ibAnswer.resmed + obResmed };
const obTotalRow = { total: obTotal, om: obOm, resmed: obResmed };

const YELLOW = '#FFFF00';
const BLUE = '#DCE6F0';
const PEACH = '#FBE0CE';
const cell = 'padding:5px 10px;border:1px solid #999;font-family:Arial,sans-serif;font-size:12px;box-sizing:border-box;white-space:nowrap;';
const nf = v => (typeof v === 'number' ? v.toLocaleString('en-IN') : v);
const COL_WIDTHS = ['220px', '130px', '130px', '130px'];

function row(label, total, om, resmed, opts) {
  opts = opts || {};
  const bg = opts.bg || '#ffffff';
  const bold = opts.bold ? 'font-weight:bold;' : '';
  const td = (v, i, align) => '<td style="' + cell + 'width:' + COL_WIDTHS[i] + ';background:' + bg + ';' + bold + (align ? 'text-align:' + align + ';' : '') + '">' + v + '</td>';
  return '<tr>' + td(label, 0) + td(nf(total), 1, 'center') + td(nf(om), 2, 'center') + td(nf(resmed), 3, 'center') + '</tr>';
}

let html = '<div style="font-family:Arial,sans-serif;">';
html += '<p style="font-weight:bold;font-style:italic;text-decoration:underline;font-size:14px;">Overall Calls Summary</p>';
html += '<table style="border-collapse:collapse;table-layout:fixed;width:610px;">';
html += '<tr><td colspan="4" style="' + cell + 'background:' + YELLOW + ';text-align:center;font-weight:bold;">' + dates.dayFormatted + '</td></tr>';
html += row('Total Calls', 'Total Calls', 'Team Open Mind', 'Team ResMed', { bg: BLUE, bold: true });
html += row('Inbound', ibTotal.total, ibTotal.om, ibTotal.resmed, { bg: PEACH, bold: true });
html += row('ANSWER', ibAnswer.total, ibAnswer.om, ibAnswer.resmed);
html += row('Agent Missed', agentMissed.total, agentMissed.om, agentMissed.resmed);
html += row('Queue Missed', queueMissed.total, queueMissed.om, queueMissed.resmed);
html += row('Ivr Missed (Working Hour)', ivrMissedWh, '-', '-');
html += row('Non Working Hour', ivrMissedNwh, '-', '-');
html += row('Outbound', obTotalRow.total, obTotalRow.om, obTotalRow.resmed, { bg: PEACH, bold: true });
html += row('Answer', obAnswer.total, obAnswer.om, obAnswer.resmed);
html += row('Noanswer', obNoAnswer.total, obNoAnswer.om, obNoAnswer.resmed);
html += row('Grand Total', grandTotal.total, grandTotal.om, grandTotal.resmed, { bg: BLUE, bold: true });
html += row('Total Handled IB + OB', totalHandled.total, totalHandled.om, totalHandled.resmed, { bg: BLUE, bold: true });
html += '</table></div>';

// --- Table 2: IVR Input Bifurcation ---
// Validated against 2026-10-19 data, every cell matched the client report
// exactly. Category comes from the note field's first comma-segment, UNLESS
// the second segment is literally 'Repeat Call' (override to 'Other Inbound')
// or the first name in received_by isn't one of our 4 OM agents (override to
// 'Handled by Sales Team', since ResMed's own staff answered it directly).
const OUR_NAMES = ['Gulshan Khan', 'Avijit Dey', 'Mohit Kumar', 'Admin', 'Sagarika Bose'];
const t2Rows = $('Exec Query Table2').all().map(item => item.json);
const colMap = v => v === 'Booking Test' ? 'Col1' : v === 'Renting CPAP and BiPAP' ? 'Col2' : v === 'Others' ? 'Col3' : 'NoIVR';
const COLS = ['Col1', 'Col2', 'Col3', 'NoIVR'];
const COL_LABELS = { Col1: 'To book a home sleep test-1', Col2: 'To rent or purchase a CPAP or BiPAP device-2', Col3: 'For device service or any other support-3', NoIVR: 'No IVR Input' };
// Fixed order/list matching the client report exactly (so a zero row like
// 'Rewards & Registration' still shows) -- any category outside this set
// (e.g. a call with no note, or stray note text) folds into 'Other Inbound'
// as a catch-all, so the grand total never silently drops a call.
const CATEGORY_ORDER = ['Sales Lead', 'Service Query', 'Rewards & Registration', 'Non Customer Query', 'Other Inbound', 'Handled by Sales Team'];

const grid = {};
const colTotals = { Col1: 0, Col2: 0, Col3: 0, NoIVR: 0 };
CATEGORY_ORDER.forEach(c => { grid[c] = { Col1: 0, Col2: 0, Col3: 0, NoIVR: 0 }; });
t2Rows.forEach(row => {
  let category;
  if (row.corrected_category) {
    // TL-submitted correction (Tracker form, 'Call Tag Correction') always wins
    // over whatever the agent originally tagged.
    category = row.corrected_category;
  } else {
    const firstReceiver = (row.received_by || '').split(',')[0].trim();
    const isOurs = OUR_NAMES.includes(firstReceiver);
    if (!isOurs) {
      category = 'Handled by Sales Team';
    } else if (row.note) {
      const parts = row.note.split(',').map(s => s.trim());
      category = (parts[1] === 'Repeat Call') ? 'Other Inbound' : parts[0];
    } else {
      category = 'Other Inbound';
    }
  }
  if (!CATEGORY_ORDER.includes(category)) category = 'Other Inbound';
  const col = colMap(row.ivr);
  grid[category][col] += 1;
  colTotals[col] += 1;
});
const catTotals = {};
CATEGORY_ORDER.forEach(c => { catTotals[c] = COLS.reduce((s, col) => s + grid[c][col], 0); });
const grandTotalT2 = Object.values(catTotals).reduce((s, v) => s + v, 0);

const COL_WIDTHS_T2 = ['180px', '160px', '190px', '190px', '110px', '90px'];
function row2(label, cells, opts) {
  opts = opts || {};
  const bg = opts.bg || '#ffffff';
  const bold = opts.bold ? 'font-weight:bold;' : '';
  const td = (v, i, align) => '<td style="' + cell + 'width:' + COL_WIDTHS_T2[i] + ';background:' + bg + ';' + bold + (align ? 'text-align:' + align + ';' : '') + '">' + v + '</td>';
  return '<tr>' + td(label, 0) + cells.map((v, i) => td(nf(v), i + 1, 'center')).join('') + '</tr>';
}

html += '<div style="font-family:Arial,sans-serif;margin-top:20px;">';
html += '<p style="font-weight:bold;font-style:italic;text-decoration:underline;font-size:14px;">Inbound - IVR Input Bifurcation</p>';
html += '<table style="border-collapse:collapse;table-layout:fixed;width:920px;">';
html += '<tr><td style="' + cell + 'width:' + COL_WIDTHS_T2[0] + ';background:' + YELLOW + ';text-align:center;font-weight:bold;">' + dates.dayFormatted + '</td><td colspan="5" style="border:none;background:transparent;padding:0;"></td></tr>';
html += row2('Inbound', [COL_LABELS.Col1, COL_LABELS.Col2, COL_LABELS.Col3, COL_LABELS.NoIVR, 'Total'], { bg: PEACH, bold: true });
CATEGORY_ORDER.forEach(catName => {
  const cells = COLS.map(c => grid[catName][c]);
  cells.push(catTotals[catName]);
  html += row2(catName, cells);
});
html += row2('Total', [colTotals.Col1, colTotals.Col2, colTotals.Col3, colTotals.NoIVR, grandTotalT2], { bg: BLUE, bold: true });
html += '</table></div>';


// --- Table 3: Bifurcation of the Calls Handled (Day + MTD) ---
// Inbound reuses Table 2's exact categories/logic (received_by-based team
// check). Outbound uses resolved_sip-based team check (Table 1's proven
// method) since received_by isn't a reliable field for who dialed out, and
// counts ALL dispositions (not just Answer) -- agents tag the campaign on
// an outbound attempt regardless of whether it connected. Both apply the
// same corrected_category override as Table 2. Validated against
// 2026-10-25 data -- every day-level cell matched the client report exactly.
const t3Rows = $('Exec Query Table3').all().map(item => item.json);
const OUTBOUND_CATEGORY_ORDER = ['OB - AirMini Upselling', 'OB - AV Registration', 'OB - Call Back on Missed Calls',
  'OB - Extended Warranty', 'OB - Feedback Calls', 'OB - Fresh HST', 'OB - Fresh HST Follow Ups',
  'OB - Inaudible or Disconnected Calls', 'OB - Resupply Follow-ups', 'OB - Sleep Quiz',
  'OB - AirSense 11 Upselling', 'Other Outbound Calls', 'Calls By Sales Team'];

function categorizeT3(row) {
  if (row.corrected_category) return row.corrected_category;
  if (row.call_type === 'INBOUND') {
    const firstReceiver = (row.received_by || '').split(',')[0].trim();
    const isOurs = OUR_NAMES.includes(firstReceiver);
    if (!isOurs) return 'Handled by Sales Team';
    if (row.note) {
      const parts = row.note.split(',').map(s => s.trim());
      return (parts[1] === 'Repeat Call') ? 'Other Inbound' : parts[0];
    }
    return 'Other Inbound';
  }
  const isOurs = row.resolved_sip && OUR_SIPS_ARR.includes(String(row.resolved_sip));
  if (!isOurs) return 'Calls By Sales Team';
  if (row.note) return row.note.split(',')[0].trim();
  return 'Other Outbound Calls';
}
const OUR_SIPS_ARR = ['10170226', '10170201', '10170203', '10170200'];

const ibDay = {}, ibMtd = {}, obDay = {}, obMtd = {};
let ibDayTotal = 0, ibMtdTotal = 0, obDayTotal = 0, obMtdTotal = 0;
t3Rows.forEach(row => {
  let cat = categorizeT3(row);
  const isInbound = row.call_type === 'INBOUND';
  const list = isInbound ? CATEGORY_ORDER : OUTBOUND_CATEGORY_ORDER;
  if (!list.includes(cat)) cat = isInbound ? 'Other Inbound' : 'Other Outbound Calls';
  const dayBucket = isInbound ? ibDay : obDay, mtdBucket = isInbound ? ibMtd : obMtd;
  mtdBucket[cat] = (mtdBucket[cat] || 0) + 1;
  if (isInbound) ibMtdTotal++; else obMtdTotal++;
  if (row.call_date === dates.day) {
    dayBucket[cat] = (dayBucket[cat] || 0) + 1;
    if (isInbound) ibDayTotal++; else obDayTotal++;
  }
});

const COL_WIDTHS_T3 = ['260px', '175px', '175px'];
function row3(label, dayV, mtdV, opts) {
  opts = opts || {};
  const bg = opts.bg || '#ffffff';
  const bold = opts.bold ? 'font-weight:bold;' : '';
  const td = (v, i, align) => '<td style="' + cell + 'width:' + COL_WIDTHS_T3[i] + ';background:' + bg + ';' + bold + (align ? 'text-align:' + align + ';' : '') + '">' + v + '</td>';
  return '<tr>' + td(label, 0) + td(nf(dayV), 1, 'center') + td(nf(mtdV), 2, 'center') + '</tr>';
}

html += '<div style="font-family:Arial,sans-serif;margin-top:20px;">';
html += '<p style="font-weight:bold;font-style:italic;text-decoration:underline;font-size:14px;">Bifurcation of the calls handled</p>';
html += '<table style="border-collapse:collapse;table-layout:fixed;width:610px;">';
html += row3('Call Type &amp; Activity', dates.dayFormatted, 'MTD', { bg: BLUE, bold: true });
html += row3('Total Calls Handled', ibDayTotal + obDayTotal, ibMtdTotal + obMtdTotal, { bg: BLUE, bold: true });
html += row3('Inbound', ibDayTotal, ibMtdTotal, { bg: PEACH, bold: true });
CATEGORY_ORDER.forEach(c => html += row3(c, ibDay[c] || 0, ibMtd[c] || 0));
html += row3('Outbound', obDayTotal, obMtdTotal, { bg: PEACH, bold: true });
OUTBOUND_CATEGORY_ORDER.forEach(c => html += row3(c, obDay[c] || 0, obMtd[c] || 0));
html += '</table></div>';

// --- Table 4: HST Conversions (Day + MTD, agent-wise) ---
const t4Rows = $('Exec Query Table4').all().map(item => item.json);
const convDay = {}, convMtd = {};
let convDayTotal = 0, convMtdTotal = 0;
t4Rows.forEach(row => {
  const firstName = (row.agent_name || 'Unassigned').split(' ')[0].trim();
  convMtd[firstName] = (convMtd[firstName] || 0) + 1;
  convMtdTotal++;
  if (row.payment_date === dates.day) {
    convDay[firstName] = (convDay[firstName] || 0) + 1;
    convDayTotal++;
  }
});
const convAgents = Object.keys(convMtd).sort();

html += '<div style="font-family:Arial,sans-serif;margin-top:20px;">';
html += '<p style="font-weight:bold;font-style:italic;text-decoration:underline;font-size:14px;">HST Conversions</p>';
html += '<table style="border-collapse:collapse;table-layout:fixed;width:610px;">';
html += '<tr>' +
  '<td style="' + cell + 'width:260px;background:' + BLUE + ';font-weight:bold;">HST Conversion</td>' +
  '<td style="' + cell + 'width:175px;background:' + YELLOW + ';text-align:center;font-weight:bold;">' + dates.dayFormatted + '</td>' +
  '<td style="' + cell + 'width:175px;background:' + BLUE + ';text-align:center;font-weight:bold;">' + dates.monthLabel + '</td></tr>';
html += '<tr>' +
  '<td style="' + cell + 'width:260px;background:' + BLUE + ';"></td>' +
  '<td style="' + cell + 'width:175px;background:' + BLUE + ';text-align:center;font-weight:bold;">HST</td>' +
  '<td style="' + cell + 'width:175px;background:' + BLUE + ';text-align:center;font-weight:bold;">MTD</td></tr>';
html += row3('Total Conversion', convDayTotal, convMtdTotal, { bg: PEACH, bold: true });
convAgents.forEach(a => html += row3(a, convDay[a] || 0, convMtd[a] || 0));
html += '</table></div>';

const subject = 'ResMed Daily Call Report - ' + dates.dayFormatted;
return [{ json: { html, subject } }];

const dates = $('Compute Dates').first().json;
// Inbound: Answer only (matches Table 2 exactly). Outbound: ALL dispositions --
// agents tag the campaign/category on an outbound attempt regardless of whether
// it connected, unlike inbound where the note describes the resolution.
// corrected_category (from the Call Tag Correction tracker type) overrides the
// note-derived category here too, same as Table 2.
const query = `SELECT DATE_FORMAT(cd.call_date, '%Y-%m-%d') AS call_date, cd.call_type, cd.received_by, cd.note, ctc.corrected_category,
  COALESCE(aan.sip, cd.agent_number) AS resolved_sip
FROM calls.call_disposition cd
LEFT JOIN calls.agent_alt_numbers aan ON aan.service_id = cd.service_id AND aan.alt_number = cd.agent_number
LEFT JOIN calls.call_tag_corrections ctc ON ctc.txn_id = cd.txn_id
WHERE cd.service_id = 1702
  AND ((cd.call_type = 'INBOUND' AND cd.disposition = 'Answer') OR cd.call_type = 'OUTBOUND')
  AND cd.call_date BETWEEN '${dates.monthStart}' AND '${dates.day}';`;
return [{ json: { query } }];

const dates = $('Compute Dates').first().json;
const query = `SELECT DATE_FORMAT(payment_date, '%Y-%m-%d') AS payment_date, agent_name
FROM calls.resmed_conversion
WHERE service_id = 1702 AND payment_date BETWEEN '${dates.monthStart}' AND '${dates.day}';`;
return [{ json: { query } }];
